using System.Text.Json.Nodes;
using LibreKO.Editors.Contracts;
using LibreKO.Editors.Core.Events;
using LibreKO.Editors.DataHost.Events;
using MySqlConnector;
public class EventReviewRegressionTests {
 [Fact] public async Task ObjectivePermutationsAndTheirHistoryReversePersist(){await EventFixture.Ensure();var service=new EventDatabase(EventFixture.Cs,Path.Combine(Path.GetTempPath(),"event-order-"+Guid.NewGuid()));var draft=EventFixture.Race(EventFixture.Id());for(var ordinal=1;ordinal<3;ordinal++){var row=EventFixture.Row(EventTable.CollectionRaceObjectives,EventFixture.Id());row["RaceId"]=draft.Original.Key.Id;row["Ordinal"]=ordinal;row["TargetId"]=880001;row["Count"]=1;EventFixture.Add(draft,EventTable.CollectionRaceObjectives,row);}Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(draft.BuildChange(Guid.NewGuid()))).Status);var original=(await service.GetAsync(draft.Original.Key))!;draft=new(original);var keys=draft.Rows.Where(r=>r.Key.Table==EventTable.CollectionRaceObjectives).OrderBy(r=>r.Key.Id).Select(r=>r.Key).ToArray();draft.Set(keys[0],"Ordinal",1);draft.Set(keys[1],"Ordinal",0);var swap=draft.BuildChange(Guid.NewGuid());var result=await service.SaveAsync(swap);Assert.True(result.Status==SaveStatus.Saved,result.Message);Assert.Equal(SaveStatus.Saved,(await service.ReplayAsync(swap.OperationId,true)).Status);draft=new((await service.GetAsync(original.Key))!);for(var i=0;i<3;i++)draft.Set(keys[i],"Ordinal",(i+1)%3);var cycle=draft.BuildChange(Guid.NewGuid());Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(cycle)).Status);Assert.Equal(SaveStatus.Saved,(await service.ReplayAsync(cycle.OperationId,true)).Status);Assert.Equal(original.Version,(await service.GetAsync(original.Key))!.Version);}
 [Fact] public async Task CustomColumnsBlockDestructiveHistoryButAllowUpdates(){await EventFixture.Ensure();await using var c=new MySqlConnection(EventFixture.Cs);await c.OpenAsync();var column="ReviewOpaque"+EventFixture.Id();await new MySqlCommand("ALTER TABLE EventTriggers ADD COLUMN "+column+" int NOT NULL DEFAULT 42",c).ExecuteNonQueryAsync();try{var root=Path.Combine(Path.GetTempPath(),"event-opaque-"+Guid.NewGuid());var service=new EventDatabase(EventFixture.Cs,root);var draft=EventFixture.New(EventFamily.NpcTrigger,EventFixture.Id());EventFixture.Add(draft,EventTable.EventTriggers,EventFixture.Row(EventTable.EventTriggers,draft.Original.Key.Id));var create=draft.BuildChange(Guid.NewGuid());Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(create)).Status);await new MySqlCommand("UPDATE EventTriggers SET "+column+"=99 WHERE `Index`="+draft.Original.Key.Id,c).ExecuteNonQueryAsync();Assert.Equal(SaveStatus.Invalid,(await service.ReplayAsync(create.OperationId,true)).Status);draft=new((await service.GetAsync(draft.Original.Key))!);draft.Set(draft.Rows[0].Key,"TriggerNum",999);Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(draft.BuildChange(Guid.NewGuid()))).Status);draft=new((await service.GetAsync(draft.Original.Key))!);draft.Remove(draft.Rows[0].Key);Assert.Equal(SaveStatus.Invalid,(await service.SaveAsync(draft.BuildChange(Guid.NewGuid()))).Status);Assert.Equal(99,Convert.ToInt32(await new MySqlCommand("SELECT "+column+" FROM EventTriggers WHERE `Index`="+draft.Original.Key.Id,c).ExecuteScalarAsync()));}finally{await new MySqlCommand("ALTER TABLE EventTriggers DROP COLUMN "+column,c).ExecuteNonQueryAsync();}}
 [Fact] public async Task ForgottenWavesRejectUnsupportedNewValuesAndPreserveExistingUnknowns(){await EventFixture.Ensure();var service=new EventDatabase(EventFixture.Cs,Path.GetTempPath(),new TestEventJournal());var before=(await service.GetAsync(new(EventFamily.Temple,5)))!;var row=EventFixture.Row(EventTable.ForgottenTempleWaves,EventFixture.Id());row["NpcId"]=880001;row["Count"]=1;var draft=new EventDraft(before);EventFixture.Add(draft,EventTable.ForgottenTempleWaves,row);Assert.Equal(SaveStatus.Invalid,(await service.SaveAsync(draft.BuildChange(Guid.NewGuid()))).Status);var added=draft.Rows.Single(r=>r.Key.Id==int.Parse(row["Id"]!.ToString()));draft.Set(added.Key,"Tier",1);draft.Set(added.Key,"Wave",1);Assert.Equal(SaveStatus.Saved,(await service.SaveAsync(draft.BuildChange(Guid.NewGuid()))).Status);var stored=added with{Values=(JsonObject)added.Values.DeepClone()};stored.Values["Tier"]=99;var next=(JsonObject)stored.Values.DeepClone();next["Count"]=2;Assert.Empty(EventRules.Validate(new(Guid.NewGuid(),new(new(EventFamily.Temple,5),[stored],"v"),[new(stored.Key,stored,next)]),service.Catalog()));}
}
